"""Source of truth for config/indicators.json. Run: python3 scripts/_indicator_defs.py"""
import json, os
CATS = [
 {"id":"curve","name":"Yield curve","weight":0.20},
 {"id":"liquidity","name":"Liquidity","weight":0.15},
 {"id":"credit","name":"Credit & banks","weight":0.25},
 {"id":"cross","name":"FX, commodities, inflation","weight":0.15},
 {"id":"vol","name":"Volatility","weight":0.10},
 {"id":"growth","name":"Labor & growth","weight":0.15},
]
def I(**k): return k
IND = [
I(id="t10y3m",name="10Y-3M Treasury spread",cat="curve",calc="level",inputs={"main":["macro/T10Y3M.csv"]},unit="pp",freq="daily",direction="lower_worse",warn=0.5,crit=0.0,
  logic="Yellow below +0.50pp (flattening); red when inverted (<0). Also flag re-steepening within 18 months of an inversion: recessions have often begun after the curve un-inverts, not during the inversion.",
  why="Compares the policy rate with the long rate. When short rates exceed long rates, bank lending margins compress and the market is pricing future cuts.",
  history={"2008":"Inverted through most of 2006-07; NBER dates the recession start to Dec 2007.","2020":"Brief inversion in 2019; the Feb 2020 recession was triggered by the pandemic, so the curve gave early but not causal warning.","2022":"Inverted from late 2022. Lead times have ranged from roughly 6 to 24 months, and the long 2022-24 inversion shows signals can be early or fail."},
  sources=["FRED T10Y3M"],track="Daily. Watch level, 3-month change (velocity) and the first close back above zero."),
I(id="t10y2y",name="10Y-2Y Treasury spread",cat="curve",calc="level",inputs={"main":["macro/T10Y2Y.csv"]},unit="pp",freq="daily",direction="lower_worse",warn=0.5,crit=0.0,
  logic="Same logic as 10Y-3M. 2Y moves on expected Fed policy, so this one reacts earlier to policy-path repricing.",
  why="The 2Y yield is the market's average expected policy rate over two years; inversion means cuts are priced in.",
  history={"2008":"Inverted Dec 2005 to mid 2007.","2020":"Inverted Aug 2019 briefly.","2022":"Inverted from July 2022, reaching roughly -100bp in March 2023 during the regional bank stress."},
  sources=["FRED T10Y2Y"],track="Daily; compare with 10Y-3M for disagreement."),
I(id="netliq",name="Fed net liquidity, 6M change",cat="liquidity",calc="net_liquidity",inputs={"walcl":["macro/WALCL.csv"],"rrp":["macro/RRPONTSYD.csv"],"tga":["macro/WTREGEN.csv"]},unit="%",freq="weekly",direction="lower_worse",warn=-2.0,crit=-6.0,window_days=182,
  logic="Net liquidity = Fed balance sheet (WALCL) minus reverse repo (RRP) minus Treasury General Account (TGA), in $bn. Score on the 6-month % change; falling liquidity is a headwind for risk assets.",
  why="Reserves are what banks and dealers use to fund balance sheets. RRP and TGA absorb reserves, so the headline balance sheet alone misleads.",
  history={"2008":"Large balance-sheet expansion (QE1) began in late 2008, close to the equity low in March 2009.","2020":"Balance sheet roughly rose from about $4T to about $7T in a few months.","2022":"QT began June 2022; RRP and TGA swings made net liquidity move differently from the headline balance sheet."},
  sources=["FRED WALCL, RRPONTSYD, WTREGEN"],track="Weekly (Thursday release). Thresholds are heuristic, tune from backtests."),
I(id="m2yoy",name="US M2 growth, YoY",cat="liquidity",calc="yoy_obs",inputs={"main":["macro/M2SL.csv"]},unit="%",freq="monthly",direction="lower_worse",warn=4.0,crit=0.0,n=12,
  logic="Yellow below 4% growth, red at or below 0% (contraction). Extreme expansion (>15%) is an inflation-risk note, not scored.",
  why="Broad money growth feeds spending and asset demand with lags. Global M2 is not freely available as a clean series; this is the US component only.",
  history={"2008":"Growth was moderate heading into the crisis.","2020":"M2 growth exceeded 20% YoY in 2020-21, followed by the 2022 inflation surge.","2022":"M2 contracted YoY in 2022-23, a sustained contraction not seen in decades."},
  sources=["FRED M2SL"],track="Monthly. Roadmap: add euro area, China, Japan aggregates (ECB, PBoC, BoJ) for a global M2."),
I(id="hyoas",name="High-yield OAS",cat="credit",calc="level",inputs={"main":["macro/BAMLH0A0HYM2.csv"]},unit="%",freq="daily",direction="higher_worse",warn=4.5,crit=6.5,
  logic="Option-adjusted spread of ICE BofA US High Yield. Yellow above 4.5%, red above 6.5%. Rate of widening matters as much as level.",
  why="Prices the default and liquidity risk of the weakest corporate borrowers; widening usually precedes or accompanies equity drawdowns.",
  history={"2008":"Spread went above 20% at the peak.","2020":"Spiked to roughly 11% in March 2020 and retraced quickly after Fed backstops.","2022":"Reached roughly 6% during the 2022 bear market."},
  sources=["FRED BAMLH0A0HYM2 (ICE data; FRED currently serves only about 3 years of history)"],track="Daily. Use 3M change as a velocity trigger."),
I(id="igoas",name="Investment-grade OAS",cat="credit",calc="level",inputs={"main":["macro/BAMLC0A0CM.csv"]},unit="%",freq="daily",direction="higher_worse",warn=1.6,crit=2.5,
  logic="Yellow above 1.6%, red above 2.5%. Compare with HY: IG widening confirms stress is spreading beyond weak borrowers.",
  why="IG stress means even high-quality issuers face higher funding costs, which hits buybacks, capex and bank balance sheets.",
  history={"2008":"IG spreads reached the 5-6% area.","2020":"Roughly 4% at the March peak.","2022":"Moderate widening, below 2%."},
  sources=["FRED BAMLC0A0CM (limited history)"],track="Daily."),
I(id="stlfsi",name="St. Louis Fed Financial Stress Index",cat="credit",calc="level",inputs={"main":["macro/STLFSI4.csv"]},unit="idx",freq="weekly",direction="higher_worse",warn=0.0,crit=1.5,
  logic="Zero is average stress. Yellow above 0, red above 1.5. A composite of rates, spreads and volatility, so it overlaps with other indicators by design.",
  why="Serves as a free composite stand-in where bank CDS spreads (proprietary) are unavailable.",
  history={"2008":"Spiked sharply in the crisis.","2020":"Spiked in March 2020.","2022":"Elevated but modest; blips in March 2023."},
  sources=["FRED STLFSI4"],track="Weekly."),
I(id="kre",name="Regional banks drawdown (KRE)",cat="credit",calc="drawdown",inputs={"main":["macro/kre.csv"]},unit="%",freq="daily",direction="lower_worse",warn=-15.0,crit=-25.0,window=252,
  logic="Percent below the trailing 12-month high of the KRE regional bank ETF. A free proxy for bank-specific stress (CDS data is not freely available).",
  why="Regional banks carry the most rate-sensitive balance sheets and deposit-run risk.",
  history={"2008":"Bank stocks fell sharply through 2007-09.","2020":"Sold off hard in March 2020, recovered after backstops.","2022":"Held up in 2022, then dropped by roughly a third within weeks in March 2023 (SVB, Signature)."},
  sources=["Yahoo Finance KRE"],track="Daily; pair with the 2Y yield to see unrealised-loss pressure."),
I(id="usd",name="US dollar momentum, 6M",cat="cross",calc="pct_chg",inputs={"main":["macro/dxy.csv","macro/DTWEXBGS.csv"]},unit="%",freq="daily",direction="higher_worse",warn=6.0,crit=12.0,days=182,
  logic="6-month % change of the dollar index. A rapid rise tightens global dollar funding and pressures emerging markets and US multinationals.",
  why="Most global debt and trade is dollar-denominated; a rising dollar is a global financial-conditions tightener.",
  history={"2008":"Dollar surged in the late-2008 flight to safety.","2020":"Spiked in March 2020 dollar shortage, then reversed on swap lines.","2022":"DXY peaked near 114 in Sept 2022 amid aggressive Fed hikes."},
  sources=["Yahoo DX-Y.NYB; fallback FRED DTWEXBGS"],track="Daily."),
I(id="cugold",name="Copper/Gold ratio, 6M change",cat="cross",calc="ratio_chg",inputs={"a":["macro/copper.csv"],"b":["macro/gold.csv"]},unit="%",freq="daily",direction="lower_worse",warn=-8.0,crit=-15.0,days=182,
  logic="Copper (growth-sensitive) divided by gold (safe haven). A sharp fall signals a global growth scare or flight to safety.",
  why="Industrial demand versus safe-haven demand. It tends to track the 10Y yield, so confirm with rates.",
  history={"2008":"Fell sharply as global growth collapsed.","2020":"Dropped in Feb-Mar 2020, rebounded quickly with stimulus.","2022":"Weakened with growth fears and a strong dollar."},
  sources=["Yahoo HG=F, GC=F"],track="Daily."),
I(id="oil",name="WTI oil, 3M move (absolute)",cat="cross",calc="pct_chg",inputs={"main":["macro/DCOILWTICO.csv","market/wti_oil.csv"]},unit="%",freq="daily",direction="higher_worse",two_sided=True,warn=25.0,crit=45.0,days=91,
  logic="Scores the absolute 3-month % change. Large rises are supply or inflation shocks; large falls usually signal demand collapse or a price war.",
  why="Oil feeds directly into headline inflation and consumer budgets, and into energy-sector credit.",
  history={"2008":"WTI peaked near $145 in July 2008, then collapsed.","2020":"Futures briefly turned negative on 20 Apr 2020.","2022":"Spiked to roughly $124 in March 2022 after Russia's invasion of Ukraine."},
  sources=["FRED DCOILWTICO; fallback WTISPLC"],track="Daily."),
I(id="be10",name="10Y breakeven inflation (de-anchoring)",cat="cross",calc="level",inputs={"main":["macro/T10YIE.csv"]},unit="%",freq="daily",direction="higher_worse",center=2.25,warn=0.5,crit=0.9,
  logic="Scores distance from a 2.25% anchor: both de-anchoring upward (inflation scare) and collapse (deflation scare) are warnings. Yellow beyond 0.5pp away, red beyond 0.9pp.",
  why="Market-implied inflation over 10 years; shows whether policy credibility is intact.",
  history={"2008":"Collapsed below 1% in late 2008 (deflation scare).","2020":"Fell to roughly 0.9% in mid-March 2020.","2022":"Peaked near 3% in spring 2022."},
  sources=["FRED T10YIE"],track="Daily; compare with 5Y5Y forward (T5YIFR)."),
I(id="vix",name="VIX",cat="vol",calc="level",inputs={"main":["macro/vix.csv"]},unit="idx",freq="daily",direction="higher_worse",warn=22.0,crit=30.0,
  logic="Yellow above 22, red above 30. Very low readings (<13) indicate complacency and are noted but not scored.",
  why="Implied S&P 500 volatility: demand for equity-index protection.",
  history={"2008":"Closing high near 81 in Nov 2008.","2020":"Closing high near 83 in March 2020.","2022":"Peaked in the mid-30s."},
  sources=["Yahoo ^VIX"],track="Daily."),
I(id="move",name="MOVE (bond volatility)",cat="vol",calc="level",inputs={"main":["macro/move.csv"]},unit="idx",freq="daily",direction="higher_worse",warn=110.0,crit=140.0,
  logic="Yellow above 110, red above 140. Bond volatility drives collateral values and funding stress, so it often leads equity volatility.",
  why="Treasuries are the collateral base of the financial system; instability there forces deleveraging.",
  history={"2008":"Above 200 in late 2008.","2020":"Spiked toward 160 in March 2020.","2022":"Around 150-160 in late 2022, then roughly 199 in March 2023."},
  sources=["Yahoo ^MOVE"],track="Daily."),
I(id="sahm",name="Sahm rule indicator",cat="growth",calc="sahm",inputs={"main":["market/unemployment_rate.csv"]},unit="pp",freq="monthly",direction="higher_worse",warn=0.3,crit=0.5,
  logic="3-month average unemployment minus its lowest value of the prior 12 months. Red at 0.5pp or more.",
  why="A real-time labor-market recession trigger: unemployment tends to accelerate once it starts rising.",
  history={"2008":"Triggered close to the start of the Dec 2007 recession.","2020":"Triggered in March-April 2020.","2022":"Not triggered in 2022; it triggered in Aug 2024 and was debated as a possible false signal because labor supply was growing."},
  sources=["FRED UNRATE (via data/market/unemployment_rate.csv)"],track="Monthly, first Friday release."),
I(id="skew",name="CBOE SKEW (experimental)",cat="vol",calc="level",inputs={"main":["macro/skew.csv"]},unit="idx",freq="daily",direction="higher_worse",warn=145.0,crit=160.0,weight=0.5,
  logic="Elevated SKEW means richer demand for out-of-the-money puts. A poor timing tool on its own; half-weighted.",
  why="Measures perceived tail risk in the S&P 500 option market.",
  history={"2008":"Not a reliable lead.","2020":"Not a reliable lead.","2022":"Not a reliable lead."},
  sources=["Yahoo ^SKEW"],track="Daily. Experimental."),
I(id="gex",name="Dealer gamma exposure, GEX (experimental)",cat="vol",calc="squeeze_gex",inputs={"main":["macro/squeeze.csv"]},unit="$bn",freq="daily",direction="lower_worse",warn=2.0,crit=0.0,weight=0.0,
  logic="Not scored (weight 0) until validated. Negative dealer gamma means hedging flows amplify moves; positive dampens them. Source is a public daily file whose availability is not guaranteed.",
  why="Dealer option hedging can amplify intraday and short-horizon moves.",
  history={"2008":"n/a","2020":"n/a","2022":"n/a"},
  sources=["SqueezeMetrics public DIX/GEX file (unofficial, may disappear)"],track="Daily; free dark-pool (DIX) and GEX data are limited, so treat as experimental."),
]
cfg={"version":1,"note":"Thresholds are heuristics for monitoring, not forecasts. Edit and rerun scripts/build_indicators.py.","regimes":[{"max":25,"label":"Calm"},{"max":45,"label":"Watch"},{"max":65,"label":"Elevated"},{"max":101,"label":"Critical"}],"categories":CATS,"indicators":IND,
 "stale_days":{"daily":10,"weekly":16,"monthly":70}}
out=os.path.join(os.path.dirname(__file__),"..","config","indicators.json")
json.dump(cfg,open(out,"w"),indent=1,ensure_ascii=False); print(len(IND),"indicators written")
